    { "^\"Teaches you how to permanently enchant a two%-handed weapon so it grants %+([%d%.]+) Spirit%.\"%.?$", "“教你学会给一件双手武器永久性地附魔，使它获得+%1精神的效果。”" },
    { "^%(([%d%.]+)%) Set: Increases your chance to resist Silence and Interrupt effects by ([%d%.]+)%%%.?$", "（%1 件）套装：使你抵抗沉默和打断效果的几率提高%2%%" },
    { "^Chance to strike your ranged target with a Quill Shot for ([%d%.]+) to ([%d%.]+) Nature damage%.?$", "有一定几率对你的远程攻击目标造成%1至%2点自然伤害" },
    { "^Chance to strike your ranged target with a Fire Blast for ([%d%.]+) to ([%d%.]+) Fire damage%.?$", "有一定几率对你的远程攻击目标造成%1至%2点火焰伤害" },
    { "^Cause party members within ([%d%.]+) yds to regenerate ([%d%.]+) health every ([%d%.]+) sec%.?$", "使%1码内的小队成员每%3秒恢复%2点生命值" },
    { "^Pummel the target for ([%d%.]+) damage and interrupt the spell being cast for ([%d%.]+) sec%.?$", "猛击目标，造成%1点伤害并打断其施法，持续%2秒" },
    { "^Knocks target silly for ([%d%.]+) sec and increases Strength by ([%d%.]+) for ([%d%.]+) sec%.?$", "命中率： 将目标打傻%1秒，使你的力量提高%2点，持续%3秒" },
    { "^\"Teaches you how to permanently enchant a weapon to regularly blast its target with fire%.\"%.?$", "“教你学会给一件武器永久性地附魔，使它可以对敌人造成火焰伤害。”" },
    { "^Increases the chance your Pick Pocket and Distract abilities are successful by ([%d%.]+)%%%.?$", "你的搜索和扰乱技能成功的几率提高%1%%" },
